        except Exception as e:
            feedback_parts.append(f"FAIL [Check 5]: Error reading Wire_Population_Q1_2026.xlsx: {e}")
            all_pass = False

    score = round(passed_checks / total_checks, 4)
    return {
        "pass": all_pass,
        "score": score,
        "feedback": "\n".join(feedback_parts)
    }

from pathlib import Path
import json
from datetime import datetime, timezone


# SOP 3.3: "Process wires in the order they appear in the workbook,
# completing all steps for each wire before moving to the next."
# Workbook order (Wire_Population_Q1_2026.xlsx rows 4-7) with each
# wire's OPS-TRE-WIRE Jira issue key.
WIRE_ORDER = [
    ("INTL-2026-0147", "OPS-2"),
    ("INTL-2026-0151", "OPS-3"),
    ("INTL-2026-0158", "OPS-4"),
    ("INTL-2026-0163", "OPS-5"),
]

# Issues present in the seeded jira_state.json. Their created stamps are
# scenario dates, not agent actions, so they carry no ordering signal.
SEED_ISSUE_KEYS = {"OPS-1", "OPS-2", "OPS-3", "OPS-4", "OPS-5", "OPS-6"}

# Only count an inversion when a later wire's action precedes an earlier
# wire's action by MORE than this many seconds. Identical stamps (e.g. a
# frozen scenario clock) and sub-second cross-service skew therefore can
# never fail a compliant run; genuine interleaving by an LLM agent is
# separated by whole tool-call turns and far exceeds this.
TOLERANCE_SECONDS = 2.0


def parse_jira_ts(value):
    """ISO-8601 (mock stamps '...Z') -> epoch seconds, or None."""
    try:
        return datetime.fromisoformat(str(value).replace("Z", "+00:00")).timestamp()
    except (ValueError, TypeError):
        return None


def parse_slack_ts(value):
    """Slack ts string ('1772636400.000100') -> epoch seconds, or None."""
    try:
        return float(value)
    except (ValueError, TypeError):
        return None


def iter_issues(issues):
    """Yield (key, issue) from a dict- or list-shaped issues container."""
    if isinstance(issues, dict):
        for key, issue in issues.items():
            if isinstance(issue, dict):
                yield str(key), issue
    elif isinstance(issues, list):
        for issue in issues:
            if isinstance(issue, dict):
                yield str(issue.get("key")), issue


def verify(workspace_path, external_services_path=None):
    if external_services_path is None:
        return {"pass": False, "score": 0.0,
                "feedback": "external_services_path is None; cannot check service state"}

    jira_path = Path(external_services_path) / "jira_state.json"
    if not jira_path.exists():
        return {"pass": False, "score": 0.0, "feedback": "jira_state.json not found"}
    with open(jira_path, encoding="utf-8") as f:
        jira = json.load(f)

    slack = {}
    slack_path = Path(external_services_path) / "slack_data.json"
    if slack_path.exists():
        with open(slack_path, encoding="utf-8") as f:
            slack = json.load(f)

    issues = jira.get("issues", {})
    all_comments = jira.get("comments", {})
    all_comments = all_comments if isinstance(all_comments, dict) else {}
    wire_ids = [wire_id for wire_id, _ in WIRE_ORDER]

    # Per-wire agent actions as (epoch_seconds, description) pairs.
    actions = {wire_id: [] for wire_id in wire_ids}
    has_record = {}

    # 1) Comments on each wire's own issue (status=verified or TRE-900 per
    #    SOP 3.3 both land here). Unstampable comments still count as the
    #    wire's outcome record but add no ordering constraint.
    for wire_id, issue_key in WIRE_ORDER:
        comments = all_comments.get(issue_key, [])
        comments = comments if isinstance(comments, list) else []
        has_record[wire_id] = len(comments) > 0
        for comment in comments:
            if not isinstance(comment, dict):
                continue
            ts = parse_jira_ts(comment.get("created"))
            if ts is not None:
                actions[wire_id].append((ts, f"comment on {issue_key}"))

    # 2) Agent-created exception issues (any non-seed issue whose summary
    #    names exactly one wire).
    for key, issue in iter_issues(issues):
        if key in SEED_ISSUE_KEYS:
            continue
        fields = issue.get("fields")
        fields = fields if isinstance(fields, dict) else {}
        summary = str(fields.get("summary", ""))
        named = [wire_id for wire_id in wire_ids if wire_id in summary]
        if len(named) != 1:
            continue
        ts = parse_jira_ts(fields.get("created"))
        if ts is not None:
            actions[named[0]].append((ts, f"creation of issue {key}"))

    # 3) #compliance-urgent (C002) messages naming exactly one wire. The
    #    channel is empty in the seed, so every entry is an agent action.
    channels = slack.get("channels") if isinstance(slack, dict) else None
    channel_id = "C002"
    if isinstance(channels, dict):
        for cid, channel in channels.items():
            if isinstance(channel, dict) and channel.get("name") == "compliance-urgent":
                channel_id = str(cid)
                break
    messages = slack.get("messages") if isinstance(slack, dict) else None
    channel_messages = messages.get(channel_id, []) if isinstance(messages, dict) else []
    channel_messages = channel_messages if isinstance(channel_messages, list) else []
    for message in channel_messages:
        if not isinstance(message, dict):
            continue
        named = [wire_id for wire_id in wire_ids if wire_id in str(message.get("text", ""))]
        if len(named) != 1:
            continue
        ts = parse_slack_ts(message.get("ts"))
        if ts is not None:
            actions[named[0]].append((ts, "#compliance-urgent message"))

    checks_passed = []
    checks_failed = []
    for wire_id, issue_key in WIRE_ORDER:
        if has_record[wire_id]:
            checks_passed.append(f"{wire_id}: outcome recorded (comment on {issue_key})")
        else:
            checks_failed.append(
                f"{wire_id}: no comment on {issue_key}; per SOP 3.3 every audited wire "
                "records its outcome on its wire issue (status=verified or TRE-900)")

    if all(has_record.values()):
        violations = []
        for i in range(len(wire_ids)):
            for j in range(i + 1, len(wire_ids)):
                earlier, later = wire_ids[i], wire_ids[j]
                if not actions[earlier] or not actions[later]:
                    continue
                last_earlier = max(actions[earlier], key=lambda action: action[0])
                first_later = min(actions[later], key=lambda action: action[0])
                if first_later[0] < last_earlier[0] - TOLERANCE_SECONDS:
                    violations.append(
                        f"{later} ({first_later[1]}) started before {earlier} "
                        f"({last_earlier[1]}) was complete")
        if violations:
            checks_failed.append(
                "out-of-order processing; SOP 3.3 requires completing all steps for "
                "each wire before moving to the next: " + "; ".join(violations))
        else:
            checks_passed.append("no later wire acted before an earlier wire was complete")
    else:
        checks_failed.append(
            "order check skipped: not every wire has a recorded outcome")

    total = 5
    passed = len(checks_passed)
    score = round(passed / total, 4)
    if checks_failed:
        return {"pass": False, "score": score,
                "feedback": f"{passed}/{total} checks passed. Failures: {checks_failed}"}
    return {"pass": True, "score": 1.0,
            "feedback": "All four wires were processed in workbook order: every wire has "
                        "its outcome comment, and no later wire's recorded action precedes "
                        "an earlier wire's final recorded action."}
